/// <summary>
/// Gets or sets the source CustConfirmJour for building the event contract.
/// </summary>
private CustConfirmJour parmCustConfirmJour(CustConfirmJour _custConfirmJour = custConfirmJour)
{
    custConfirmJour = _custConfirmJour;

    return custConfirmJour;
}

/// <summary>
/// Creates a new <c>AAXSalesOrderConfirmedBusinessEvent</c> instance from the specified <c>CustConfirmJour</c> record.
/// </summary>
/// <param name="_custConfirmJour">The source CustConfirmJour record.</param>
/// <returns>A new instance of <c>AAXSalesOrderConfirmedBusinessEvent</c>.</returns>
public static AAXSalesOrderConfirmedBusinessEvent newFromCustConfirmJour(CustConfirmJour _custConfirmJour)
{
    AAXSalesOrderConfirmedBusinessEvent businessEvent = new AAXSalesOrderConfirmedBusinessEvent();
    businessEvent.parmCustConfirmJour(_custConfirmJour);

    return businessEvent;
}

/// <summary>
/// Private constructor. Use static factory methods to create instances.
/// </summary>
private void new()
{
}

/// <summary>
/// Builds the data contract for this business event.
/// </summary>
/// <returns>The populated <c>AAXSalesOrderConfirmedBusinessEventContract</c>.</returns>
[Wrappable(true), Replaceable(true)]
public BusinessEventsContract buildContract()
{
    return AAXSalesOrderConfirmedBusinessEventContract::newFromCustConfirmJour(custConfirmJour);
}
